
create table if not exists public.iom_profiles(id uuid primary key references auth.users(id) on delete cascade,email text,name text,role text not null default 'Auditor',active boolean not null default false,created_at timestamptz default now());
create table if not exists public.iom_state(id int primary key,data jsonb,version int,updated_at timestamptz default now(),updated_by uuid);
create table if not exists public.iom_attachments(id uuid primary key default gen_random_uuid(),link_type text,link_ref text,filename text,path text,size bigint,uploaded_by uuid default auth.uid(),created_at timestamptz default now());
create table if not exists public.iom_backups(id bigint generated by default as identity primary key,taken_at timestamptz default now(),version int,data jsonb);
alter table iom_profiles enable row level security; alter table iom_state enable row level security; alter table iom_attachments enable row level security; alter table iom_backups enable row level security;
create or replace function public.iom_is_active() returns boolean language sql stable security definer set search_path to 'public' as $$ select coalesce((select active from iom_profiles where id=auth.uid()),false) $$;
create or replace function public.iom_can_write() returns boolean language sql stable security definer set search_path to 'public' as $$ select coalesce((select active and role<>'Auditor' from iom_profiles where id=auth.uid()),false) $$;
create or replace function public.iom_is_admin() returns boolean language sql stable security definer set search_path to 'public' as $$ select coalesce((select active and role='General Manager' from iom_profiles where id=auth.uid()),false) $$;
create or replace function public.iom_ensure_profile() returns void language plpgsql security definer set search_path to 'public' as $$
declare em text; n int; begin if auth.uid() is null then return; end if;
 select email into em from auth.users where id=auth.uid();
 select count(*) into n from iom_profiles where role='General Manager';
 insert into iom_profiles(id,email,name,role,active) values(auth.uid(),em,split_part(em,'@',1),case when n=0 and lower(em)='fathyeid620@gmail.com' then 'General Manager' else 'Auditor' end,(n=0 and lower(em)='fathyeid620@gmail.com')) on conflict do nothing; end $$;
grant execute on function public.iom_ensure_profile() to authenticated;
drop policy if exists p_upd on iom_profiles; drop policy if exists p_sel on iom_profiles;
create policy p_upd on iom_profiles for update using (iom_is_admin()) with check (iom_is_admin());
create policy p_sel on iom_profiles for select using (id=auth.uid() or iom_is_active());
drop policy if exists s_upd on iom_state; drop policy if exists s_ins on iom_state; drop policy if exists s_sel on iom_state;
create policy s_upd on iom_state for update using (iom_can_write()) with check (iom_can_write());
create policy s_ins on iom_state for insert with check (iom_can_write());
create policy s_sel on iom_state for select using (iom_is_active());
drop policy if exists a_ins on iom_attachments; drop policy if exists a_sel on iom_attachments;
create policy a_ins on iom_attachments for insert with check (iom_can_write());
create policy a_sel on iom_attachments for select using (iom_is_active());
drop policy if exists gm_ins on iom_backups; drop policy if exists gm_read on iom_backups;
create policy gm_ins on iom_backups for insert with check (iom_is_admin());
create policy gm_read on iom_backups for select using (iom_is_admin());
insert into storage.buckets(id,name,public) values('iom-files','iom-files',false) on conflict do nothing;
drop policy if exists iom_f_ins on storage.objects; drop policy if exists iom_f_sel on storage.objects;
create policy iom_f_ins on storage.objects for insert with check (bucket_id='iom-files' and public.iom_can_write());
create policy iom_f_sel on storage.objects for select using (bucket_id='iom-files' and public.iom_is_active());
do $$ begin alter publication supabase_realtime add table public.iom_state; exception when duplicate_object then null; end $$;
